import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

export const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: '1', name: 'lookup', input: {}}};
export const DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

export const usageStop = (stopReason: string, usage?: UsageMetadata): MessageChunk => ({
  type: 'stop',
  stopReason,
  usage,
});

export const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield* rounds[round++] ?? [];
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

export const createTestSession = (content = 'Use the tools.'): ChatSession => ({
  sessionId: 'test-session',
  userId: 'test-user',
  entries: [{role: 'user', content, timestamp: '2026-01-01T00:00:00.000Z'}],
});

import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {UsageMetadata} from '../types/ai.js';
import {scriptedProvider, usageStop, createTestSession, TOOL_CALL} from './orchestratorTestSupport.js';

const promptBuilder = new PromptBuilder({identity: 'Usage acceptance test.'});

const lookupRegistry = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'Looks up a value.', inputSchema: {type: 'object'}},
    async () => 'found'
  );
  return registry;
};

describe('afterModelResponse usage across tool rounds', () => {
  it('reports the summed usage from every provider call in a turn with two tool rounds', async () => {
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 11, outputTokens: 2, totalTokens: 13})],
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 23, outputTokens: 3, totalTokens: 26})],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 37, outputTokens: 5, totalTokens: 42})],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );

    await orchestrator.processMessage(createTestSession());

    expect(reported).toEqual({inputTokens: 71, outputTokens: 10, totalTokens: 81});
  });

  it('counts reported rounds while leaving a turn with no reported usage undefined', async () => {
    const reports: Array<UsageMetadata | undefined> = [];
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reports.push(usage);
      },
    };
    const withGaps = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 2, outputTokens: 1, totalTokens: 3})],
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 7, outputTokens: 4, totalTokens: 11})],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );
    const withoutUsage = createChatOrchestrator(
      scriptedProvider([[{type: 'text', text: 'Done.'}, {type: 'stop', stopReason: 'end_turn'}]]),
      promptBuilder,
      undefined,
      {hooks}
    );

    await withGaps.processMessage(createTestSession());
    await withoutUsage.processMessage(createTestSession());

    expect(reports).toEqual([{inputTokens: 9, outputTokens: 5, totalTokens: 14}, undefined]);
  });
});

import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {UsageMetadata} from '../types/ai.js';
import {scriptedProvider, usageStop, createTestSession, TOOL_CALL} from './orchestratorTestSupport.js';

describe('ChatOrchestrator usage accumulation', () => {
  const promptBuilder = new PromptBuilder({identity: 'Test.'});

  it('accumulates usage across multiple rounds', async () => {
    let capturedUsage: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_s, _t, usage) => {
        capturedUsage = usage;
      },
    };

    const registry = new ToolRegistry();
    registry.register({name: 'lookup', description: 'd', inputSchema: {}}, async () => 'r');

    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, usageStop('tool_use', {inputTokens: 10, outputTokens: 5, totalTokens: 15})],
        [{type: 'text', text: 'Done.'}, usageStop('end_turn', {inputTokens: 20, outputTokens: 10, totalTokens: 30})],
      ]),
      promptBuilder,
      registry,
      {hooks}
    );

    await orchestrator.processMessage(createTestSession());

    expect(capturedUsage).toEqual({
      inputTokens: 30,
      outputTokens: 15,
      totalTokens: 45,
    });
  });

  it('reports undefined when no rounds report usage', async () => {
    let capturedUsage: any = 'not-called';
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_s, _t, usage) => {
        capturedUsage = usage;
      },
    };

    const orchestrator = createChatOrchestrator(
      scriptedProvider([[{type: 'text', text: 'Done.'}, {type: 'stop', stopReason: 'end_turn'}]]),
      promptBuilder,
      undefined,
      {hooks}
    );

    await orchestrator.processMessage(createTestSession());

    expect(capturedUsage).toBeUndefined();
  });
});

